function openJournal(chunks) {
  let iterator = null;
  let sourceDone = false;
  let ended = false;
  let closed = false;

  let currentChunk = null;
  let currentOffset = 0;

  let lineNumber = 1;
  let lineHasBytes = false;
  let lineParts = [];
  let lineDecoder = new TextDecoder("utf-8", { ignoreBOM: true });

  let acquiring = false;
  let acquisitionWait = null;
  let resolveAcquisition = null;

  let returnPromise = null;
  let closePromise = null;

  function doneResult() {
    return { done: true, value: undefined };
  }

  function discardBufferedData() {
    currentChunk = null;
    currentOffset = 0;
    lineHasBytes = false;
    lineParts = [];
    lineDecoder = null;
  }

  function acquireIterator() {
    acquiring = true;
    acquisitionWait = new Promise((resolve) => {
      resolveAcquisition = resolve;
    });

    try {
      const method = chunks[Symbol.asyncIterator];

      if (typeof method !== "function") {
        throw new TypeError("chunks is not an async iterable");
      }

      iterator = method.call(chunks);
    } finally {
      acquiring = false;
      resolveAcquisition();
      resolveAcquisition = null;
    }
  }

  function returnSource() {
    if (returnPromise !== null) {
      return returnPromise;
    }

    if (iterator === null || sourceDone) {
      return Promise.resolve();
    }

    const target = iterator;

    returnPromise = Promise.resolve()
      .then(() => {
        const method = target.return;

        if (typeof method === "function") {
          return method.call(target);
        }
      })
      .then(() => undefined);

    return returnPromise;
  }

  function appendBytes(bytes) {
    if (bytes.byteLength === 0) {
      return;
    }

    lineHasBytes = true;

    const text = lineDecoder.decode(bytes, { stream: true });
    if (text.length !== 0) {
      lineParts.push(text);
    }
  }

  function finishLine(stripCarriageReturn) {
    const tail = lineDecoder.decode();

    if (tail.length !== 0) {
      lineParts.push(tail);
    }

    let text =
      lineParts.length === 1 ? lineParts[0] : lineParts.join("");

    if (
      stripCarriageReturn &&
      text.length !== 0 &&
      text.charCodeAt(text.length - 1) === 13
    ) {
      text = text.slice(0, -1);
    }

    lineParts = [];
    lineHasBytes = false;
    lineDecoder = new TextDecoder("utf-8", { ignoreBOM: true });

    return text;
  }

  function makeEvent(text, line) {
    if (text.trim() === "") {
      return null;
    }

    try {
      return {
        line,
        ok: true,
        value: JSON.parse(text)
      };
    } catch {
      return {
        line,
        ok: false,
        text
      };
    }
  }

  async function next() {
    if (closed || ended) {
      return doneResult();
    }

    try {
      if (iterator === null) {
        acquireIterator();

        if (closed) {
          return doneResult();
        }
      }

      while (true) {
        if (closed) {
          return doneResult();
        }

        if (currentChunk !== null) {
          const length = currentChunk.byteLength;

          if (currentOffset >= length) {
            currentChunk = null;
            currentOffset = 0;
            continue;
          }

          const newlineIndex = Uint8Array.prototype.indexOf.call(
            currentChunk,
            10,
            currentOffset
          );

          if (newlineIndex === -1) {
            appendBytes(
              Uint8Array.prototype.subarray.call(
                currentChunk,
                currentOffset,
                length
              )
            );

            currentChunk = null;
            currentOffset = 0;
            continue;
          }

          appendBytes(
            Uint8Array.prototype.subarray.call(
              currentChunk,
              currentOffset,
              newlineIndex
            )
          );

          currentOffset = newlineIndex + 1;

          if (currentOffset >= length) {
            currentChunk = null;
            currentOffset = 0;
          }

          const text = finishLine(true);
          const physicalLine = lineNumber++;
          const event = makeEvent(text, physicalLine);

          if (event !== null) {
            return { done: false, value: event };
          }

          continue;
        }

        const step = await iterator.next();

        if (closed) {
          return doneResult();
        }

        const isDone = Boolean(step.done);

        if (closed) {
          return doneResult();
        }

        if (isDone) {
          sourceDone = true;
          ended = true;

          if (!lineHasBytes) {
            discardBufferedData();
            return doneResult();
          }

          const text = finishLine(false);
          const physicalLine = lineNumber++;
          const event = makeEvent(text, physicalLine);

          discardBufferedData();

          if (event === null) {
            return doneResult();
          }

          return { done: false, value: event };
        }

        const value = step.value;

        if (closed) {
          return doneResult();
        }

        currentChunk = value;
        currentOffset = 0;
      }
    } catch (error) {
      ended = true;
      closed = true;
      discardBufferedData();

      try {
        await returnSource();
      } catch {
        // Preserve and propagate the original read error.
      }

      throw error;
    }
  }

  function close() {
    if (closePromise !== null) {
      return closePromise;
    }

    closed = true;
    ended = true;
    discardBufferedData();

    const waitForAcquisition =
      acquiring && acquisitionWait !== null
        ? acquisitionWait
        : Promise.resolve();

    closePromise = waitForAcquisition
      .then(() => returnSource())
      .then(() => undefined);

    return closePromise;
  }

  return { next, close };
}
